(4999673, 727692, 69192, '<td valign="top">Cute, but the background is blown out (intentional?).  A more downward angle could help to get rid of the bright background and focus more on the girls.</td>', 'Cute, but the background is blown out (intentional?).  A more downward angle could help to get rid of the bright background and focus more on the girls.', '2008-10-08 14:35:07.000000', NULL, 1),
(4999678, 728995, 69192, '<td valign="top">Awww!  Puppies!  Nice DOF on the background.</td>', 'Awww!  Puppies!  Nice DOF on the background.', '2008-10-08 14:36:04.000000', NULL, 1),
(4999679, 728930, 69192, '<td valign="top">Very nice, but a tighter crop would make this picture so much more effective.</td>', 'Very nice, but a tighter crop would make this picture so much more effective.', '2008-10-08 14:36:39.000000', NULL, 1),
(4999681, 729338, 69192, '<td valign="top">So many contrasting colors, but still the focus remains on the child''s face - nice work!</td>', 'So many contrasting colors, but still the focus remains on the child''s face - nice work!', '2008-10-08 14:37:18.000000', NULL, 1),
(4999683, 728274, 69192, '<td valign="top">This makes me a little nervous!  =)  I''m not sure I like that the child''s head is chopped off, but this is a very creative idea!</td>', 'This makes me a little nervous!  =)  I''m not sure I like that the child''s head is chopped off, but this is a very creative idea!', '2008-10-08 14:38:36.000000', NULL, 1),
(4999685, 729130, 69192, '<td valign="top">I don''t understand how this represents play or even foreplay, but it''s a very interesting picture.</td>', 'I don''t understand how this represents play or even foreplay, but it''s a very interesting picture.', '2008-10-08 14:39:26.000000', NULL, 1),
(4999689, 728914, 69192, '<td valign="top">Could use more contrast to really bring out the blues or even some blue saturation.  The crop close to the head is a little tight for me as well.</td>', 'Could use more contrast to really bring out the blues or even some blue saturation.  The crop close to the head is a little tight for me as well.', '2008-10-08 14:40:15.000000', NULL, 1),
(4999691, 728809, 69192, '<td valign="top">Very beautiful calm colors!</td>', 'Very beautiful calm colors!', '2008-10-08 14:40:46.000000', NULL, 1),
(4999693, 728750, 69192, '<td valign="top">Very nice take on the subject!  You can really see the connection of the horse and rider here.  8</td>', 'Very nice take on the subject!  You can really see the connection of the horse and rider here.  8', '2008-10-08 14:41:35.000000', NULL, 1),
(4999695, 728928, 69192, '<td valign="top">I''d like to see people playing in this picture.</td>', 'I''d like to see people playing in this picture.', '2008-10-08 14:42:07.000000', NULL, 1),
(4999696, 729009, 69192, '<td valign="top">Very crisp details!</td>', 'Very crisp details!', '2008-10-08 14:42:23.000000', NULL, 1),
(4999700, 728625, 69192, '<td valign="top">Maybe a slower shutter speed might look a little better because the lights would be more of a continuation instead of jagged.</td>', 'Maybe a slower shutter speed might look a little better because the lights would be more of a continuation instead of jagged.', '2008-10-08 14:43:26.000000', NULL, 1),
(4999704, 729369, 69192, '<td valign="top">A hand holding these cards would be more interesting.  Maybe some other people playing in the background.  A pile in the middle if there are discarded cards in this game.  The lighting could use some work as well, although I know that it is hard to light this type of situation.</td>', 'A hand holding these cards would be more interesting.  Maybe some other people playing in the background.  A pile in the middle if there are discarded cards in this game.  The lighting could use some work as well, although I know that it is hard to light this type of situation.', '2008-10-08 14:44:37.000000', NULL, 1),
(4999706, 729377, 69192, '<td valign="top">A tighter crop on the boy would have eliminated all the distracting elements in the background.</td>', 'A tighter crop on the boy would have eliminated all the distracting elements in the background.', '2008-10-08 14:45:19.000000', NULL, 1),
(4999707, 728884, 69192, '<td valign="top">Nice wide view to show all the elements of the contest.</td>', 'Nice wide view to show all the elements of the contest.', '2008-10-08 14:45:59.000000', NULL, 1),
(4999711, 728379, 69192, '<td valign="top">More saturation in the color of the grass and sky might improve this image.</td>', 'More saturation in the color of the grass and sky might improve this image.', '2008-10-08 14:46:45.000000', NULL, 1),
(4999715, 728728, 69192, '<td valign="top">A tighter crop on the hand and the guitar would help to focus more on the main subject.</td>', 'A tighter crop on the hand and the guitar would help to focus more on the main subject.', '2008-10-08 14:47:34.000000', NULL, 1),
(4999720, 729316, 69192, '<td valign="top">I feel this would be a great subject for this challenge, but if it was actually moving and you were panning with it.</td>', 'I feel this would be a great subject for this challenge, but if it was actually moving and you were panning with it.', '2008-10-08 14:48:17.000000', NULL, 1),
(4999725, 728817, 69192, '<td valign="top">Might be improved if the boy was looking up or more forward.</td>', 'Might be improved if the boy was looking up or more forward.', '2008-10-08 14:49:49.000000', NULL, 1),
(4999726, 728935, 69192, '<td valign="top">This photo doesn''t indicate "play" to me.</td>', 'This photo doesn''t indicate "play" to me.', '2008-10-08 14:50:25.000000', NULL, 1),
(4999730, 728468, 69192, '<td valign="top">Very nice picture of a mother and child!</td>', 'Very nice picture of a mother and child!', '2008-10-08 14:51:14.000000', NULL, 1),
(4999732, 729008, 69192, '<td valign="top">A closer shot of this car and the driver would be much more interesting.</td>', 'A closer shot of this car and the driver would be much more interesting.', '2008-10-08 14:51:38.000000', NULL, 1),
(4999734, 728549, 69192, '<td valign="top">Very cute idea and interesting angle!</td>', 'Very cute idea and interesting angle!', '2008-10-08 14:52:37.000000', NULL, 1),
(4999736, 729285, 69192, '<td valign="top">Cute kid!  A more downward angle would eliminate the platform in the background and focus more on the boy.</td>', 'Cute kid!  A more downward angle would eliminate the platform in the background and focus more on the boy.', '2008-10-08 14:53:40.000000', NULL, 1),
