(4999746, 729205, 69192, '<td valign="top">Very nice DOF!</td>', 'Very nice DOF!', '2008-10-08 14:55:39.000000', NULL, 1),
(4999751, 728838, 69192, '<td valign="top">I like the black and white effect on this picture!</td>', 'I like the black and white effect on this picture!', '2008-10-08 14:56:22.000000', NULL, 1),
